// Clean-room TSVC s116 profile; see package rights note.
#[no_mangle]
pub unsafe extern "C" fn tsvc_s116_unrolled_product_chain(input:*const i64,length:usize,output:*mut u8,capacity:usize)->i64{if input.is_null()||length<8||length>23{return -1;}let v=core::slice::from_raw_parts(input,length);let nr=v[0];let passes=v[1];if !(6..=21).contains(&nr)||(nr-1)%5!=0||!(1..=4).contains(&passes){return -1;}let n=nr as usize;if length!=2+n{return -1;}let mut a=[0i64;21];for k in 0..n{if v[2+k]!=-1&&v[2+k]!=1{return -1;}a[k]=v[2+k];}if output.is_null()||capacity<8*n{return -2;}for _ in 0..passes{let mut i=0;while i<n-5{a[i]=a[i+1]*a[i];a[i+1]=a[i+2]*a[i+1];a[i+2]=a[i+3]*a[i+2];a[i+3]=a[i+4]*a[i+3];a[i+4]=a[i+5]*a[i+4];i+=5;}}for k in 0..n{let bits=a[k] as u64;for j in 0..8{output.add(8*k+j).write((bits>>(8*j))as u8);}}n as i64}
